window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5cf2aa6203ebcfa7"]={"versions": [{"id": "FIG-5cf2aa6203ebcfa7", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Signalflussdiagramm zur Gegenüberstellung der Hardware-Signalverarbeitungskette und der korrespondierenden AUTOSAR-Software-Schichtenarchitektur innerhalb eines Steuergeräts (ECU). Das Diagramm teilt sich über eine horizontale Trennlinie in eine obere Hardware-/Physikebene und eine untere Softwareebene, wobei ein vertikaler Pfeil den Übergang von den Mikrocontroller-Peripherien (<code>µC Peripherals</code>) zur hardwarenahen Treiberschicht (<code>MCAL</code>) markiert. Ergänzend sind diskrete Signal- und Schnittstellenübergänge (Ziffern 1 bis 6) eingezeichnet.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst auf Hardwareebene die Entitäten:</p>\n<ul class=\"fig-list\">\n<li><code>Car environment</code>: Physikalische Fahrzeugumgebung als Signalursprung.</li>\n<li><code>Sensor</code>: Physischer Sensor (cyan markiert).</li>\n<li><code>ECU Electronics</code>: Steuergeräte-Elektronik / Signalaufbereitung (gelb markiert).</li>\n<li><code>µC Peripherals</code>: Mikrocontroller-Peripheriebausteine (grau markiert).</li>\n</ul>\n<p class=\"fig-p\">Auf Softwareebene korrespondieren dazu:</p>\n<ul class=\"fig-list\">\n<li><code>MCAL</code>: Microcontroller Abstraction Layer (grau markiert), abstrahiert die <code>µC Peripherals</code>.</li>\n<li><code>ECU Abstraction</code>: Steuergeräte-Abstraktionsschicht (gelb markiert), korrespondiert zur <code>ECU Electronics</code>.</li>\n<li><code>Sensor SW-C</code>: Sensor-Softwarekomponente (cyan markiert), korrespondiert zum physikalischen <code>Sensor</code>.</li>\n<li><code>Application SW-C</code>: Anwendungs-Softwarekomponente, konsumiert verarbeitete Sensordaten.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Verbindungspunkte:</p>\n<ul class=\"fig-list\">\n<li>Übergang 1: Physikalische Messgröße aus der Umgebung zum Sensor.</li>\n<li>Übergang 2: Elektrisches Signal (z. B. Sensorstrom/Spannung) vom Sensor zur Steuergeräte-Elektronik.</li>\n<li>Übergang 3: Aufbereitetes Signal von der ECU-Elektronik an Peripherie-Pins des Mikrocontrollers.</li>\n<li>Übergang 4: Client-Server- oder Driver-Schnittstellen zwischen <code>ECU Abstraction</code> und <code>MCAL</code> mit den Operationen <code>DIO_set()</code> und <code>ADC_get()</code>.</li>\n<li>Übergang 5: Schnittstelle zwischen <code>Sensor SW-C</code> und <code>ECU Abstraction</code> über die Operation <code>get_I_sensor()</code>.</li>\n<li>Übergang 6: Schnittstelle zwischen <code>Application SW-C</code> und <code>Sensor SW-C</code> über die Operation <code>get_v()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der funktionale Signal- und Datenfluss erfolgt entlang zweier gekoppelter Pfade:</p>\n<ol class=\"fig-list\">\n<li>Physikalische Erfassung: Die Messgröße wird aus dem <code>Car environment</code> (1) vom <code>Sensor</code> aufgenommen, als Rohsignal (2) über die <code>ECU Electronics</code> konditioniert und über elektrische Eingänge (3) an die <code>µC Peripherals</code> geleitet.</li>\n<li>Hardware-zu-Software-Übergang: Die Hardware-Zustände der Peripherieeinheiten werden vom Microcontroller Abstraction Layer (<code>MCAL</code>) erfasst.</li>\n<li>Softwarebasierte Verarbeitung: Die <code>ECU Abstraction</code> steuert bzw. liest die Treiberebene über <code>DIO_set()</code> und <code>ADC_get()</code> (4). Die <code>Sensor SW-C</code> fragt Messgrößen (z. B. Sensorstrom via <code>get_I_sensor()</code>, 5) von der <code>ECU Abstraction</code> ab, transformiert diese in physikalische Größen (z. B. Geschwindigkeit via <code>get_v()</code>, 6) und stellt sie der <code>Application SW-C</code> bereit.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild veranschaulicht das AUTOSAR-Abstraktionsprinzip für Sensorik nach dem Resource Template bzw. Virtual Functional Bus (VFB):</p>\n<ul class=\"fig-list\">\n<li>Trennung von hardwareabhängiger Signalaufbereitung (<code>ECU Abstraction</code> / <code>MCAL</code>) und sensorspezifischer Logik (<code>Sensor SW-C</code>).</li>\n<li>Hardwarenahe Basistreiber (ADC, DIO) werden in der MCAL gekapselt und von der ECU-Abstraktion bedient.</li>\n<li>Applikationskomponenten greifen ausschließlich über standardisierte AUTOSAR-Ports/Interfaces auf logische Sensordaten (<code>Sensor SW-C</code>) zu, ohne direkte Kopplung an physikalische Peripherien oder Schaltungseigenschaften der ECU.</li>\n</ul>"}, {"id": "FIG-47fca2dccb289841", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Signalflussdiagramm zur Gegenüberstellung der Hardware-Signalverarbeitungskette und der korrespondierenden AUTOSAR-Software-Schichtenarchitektur innerhalb eines Steuergeräts (ECU). Das Diagramm teilt sich über eine horizontale Trennlinie in eine obere Hardware-/Physikebene und eine untere Softwareebene, wobei ein vertikaler Pfeil den Übergang von den Mikrocontroller-Peripherien (<code>µC Peripherals</code>) zur hardwarenahen Treiberschicht (<code>MCAL</code>) markiert. Ergänzend sind diskrete Signal- und Schnittstellenübergänge (Ziffern 1 bis 6) eingezeichnet.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst auf Hardwareebene die Entitäten:</p>\n<ul class=\"fig-list\">\n<li><code>Car environment</code>: Physikalische Fahrzeugumgebung als Signalursprung.</li>\n<li><code>Sensor</code>: Physischer Sensor (cyan markiert).</li>\n<li><code>ECU Electronics</code>: Steuergeräte-Elektronik / Signalaufbereitung (gelb markiert).</li>\n<li><code>µC Peripherals</code>: Mikrocontroller-Peripheriebausteine (grau markiert).</li>\n</ul>\n<p class=\"fig-p\">Auf Softwareebene korrespondieren dazu:</p>\n<ul class=\"fig-list\">\n<li><code>MCAL</code>: Microcontroller Abstraction Layer (grau markiert), abstrahiert die <code>µC Peripherals</code>.</li>\n<li><code>ECU Abstraction</code>: Steuergeräte-Abstraktionsschicht (gelb markiert), korrespondiert zur <code>ECU Electronics</code>.</li>\n<li><code>Sensor SW-C</code>: Sensor-Softwarekomponente (cyan markiert), korrespondiert zum physikalischen <code>Sensor</code>.</li>\n<li><code>Application SW-C</code>: Anwendungs-Softwarekomponente, konsumiert verarbeitete Sensordaten.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Verbindungspunkte:</p>\n<ul class=\"fig-list\">\n<li>Übergang 1: Physikalische Messgröße aus der Umgebung zum Sensor.</li>\n<li>Übergang 2: Elektrisches Signal (z. B. Sensorstrom/Spannung) vom Sensor zur Steuergeräte-Elektronik.</li>\n<li>Übergang 3: Aufbereitetes Signal von der ECU-Elektronik an Peripherie-Pins des Mikrocontrollers.</li>\n<li>Übergang 4: Client-Server- oder Driver-Schnittstellen zwischen <code>ECU Abstraction</code> und <code>MCAL</code> mit den Operationen <code>DIO_set()</code> und <code>ADC_get()</code>.</li>\n<li>Übergang 5: Schnittstelle zwischen <code>Sensor SW-C</code> und <code>ECU Abstraction</code> über die Operation <code>get_I_sensor()</code>.</li>\n<li>Übergang 6: Schnittstelle zwischen <code>Application SW-C</code> und <code>Sensor SW-C</code> über die Operation <code>get_v()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der funktionale Signal- und Datenfluss erfolgt entlang zweier gekoppelter Pfade:</p>\n<ol class=\"fig-list\">\n<li>Physikalische Erfassung: Die Messgröße wird aus dem <code>Car environment</code> (1) vom <code>Sensor</code> aufgenommen, als Rohsignal (2) über die <code>ECU Electronics</code> konditioniert und über elektrische Eingänge (3) an die <code>µC Peripherals</code> geleitet.</li>\n<li>Hardware-zu-Software-Übergang: Die Hardware-Zustände der Peripherieeinheiten werden vom Microcontroller Abstraction Layer (<code>MCAL</code>) erfasst.</li>\n<li>Softwarebasierte Verarbeitung: Die <code>ECU Abstraction</code> steuert bzw. liest die Treiberebene über <code>DIO_set()</code> und <code>ADC_get()</code> (4). Die <code>Sensor SW-C</code> fragt Messgrößen (z. B. Sensorstrom via <code>get_I_sensor()</code>, 5) von der <code>ECU Abstraction</code> ab, transformiert diese in physikalische Größen (z. B. Geschwindigkeit via <code>get_v()</code>, 6) und stellt sie der <code>Application SW-C</code> bereit.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild veranschaulicht das AUTOSAR-Abstraktionsprinzip für Sensorik nach dem Resource Template bzw. Virtual Functional Bus (VFB):</p>\n<ul class=\"fig-list\">\n<li>Trennung von hardwareabhängiger Signalaufbereitung (<code>ECU Abstraction</code> / <code>MCAL</code>) und sensorspezifischer Logik (<code>Sensor SW-C</code>).</li>\n<li>Hardwarenahe Basistreiber (ADC, DIO) werden in der MCAL gekapselt und von der ECU-Abstraktion bedient.</li>\n<li>Applikationskomponenten greifen ausschließlich über standardisierte AUTOSAR-Ports/Interfaces auf logische Sensordaten (<code>Sensor SW-C</code>) zu, ohne direkte Kopplung an physikalische Peripherien oder Schaltungseigenschaften der ECU.</li>\n</ul>"}], "trans": [{"from": "FIG-5cf2aa6203ebcfa7", "to": "FIG-47fca2dccb289841", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
